package dev.mineagent.runtime.neoforge.client.nativeui;
import com.google.gson.*;import com.lowdragmc.lowdraglib2.gui.ui.UIElement;import dev.mineagent.runtime.neoforge.network.UiPayloads;import net.minecraft.client.Minecraft;import net.minecraft.network.chat.Component;import java.io.*;import java.util.*;
/** Native read-only image/document cards and explicitly enabled game captures. */
public final class NativeResourceView {
 private static final Map<UUID,Pending> PENDING=new LinkedHashMap<>();private record Pending(Object connection,JsonObject header,ByteArrayOutputStream bytes){}private static Object connection;
 private static final java.util.concurrent.ExecutorService IMAGES=java.util.concurrent.Executors.newFixedThreadPool(2,Thread.ofVirtual().name("resource-image-",0).factory());
 private static final Map<net.minecraft.resources.Identifier,WorkspaceWindow> TEXTURES=new LinkedHashMap<>();
 public static void tick(){var mc=Minecraft.getInstance();if(connection!=mc.getConnection()){PENDING.clear();for(var id:List.copyOf(TEXTURES.keySet()))release(id);connection=mc.getConnection();}}
 private static void release(net.minecraft.resources.Identifier id){if(TEXTURES.remove(id)!=null)Minecraft.getInstance().getTextureManager().release(id);}
 public static void workspaceRemoved(){for(var id:List.copyOf(TEXTURES.keySet()))release(id);}
 public static void accept(UiPayloads.Event packet){var mc=Minecraft.getInstance();if(connection!=mc.getConnection()){PENDING.clear();connection=mc.getConnection();}try{var data=JsonParser.parseString(packet.json()).getAsJsonObject();String kind=data.get("kind").getAsString();if(kind.equals("capture")){capture(packet.requestId(),data);return;}if(kind.equals("preview")){int size=data.get("total").getAsInt();if(size<0||size>dev.mineagent.runtime.api.model.ModelImage.MAX_BYTES||PENDING.size()>=8)throw new IllegalArgumentException("RESOURCE_PREVIEW_LIMIT");var pending=new Pending(connection,data,new ByteArrayOutputStream());if(size==0)show(packet.requestId(),pending);else PENDING.put(packet.requestId(),pending);return;}var pending=PENDING.get(packet.requestId());if(pending==null||pending.connection()!=mc.getConnection())return;byte[] bytes=Base64.getDecoder().decode(data.get("data").getAsString());int total=pending.header().get("total").getAsInt();if(data.get("offset").getAsInt()!=pending.bytes().size()||bytes.length>18000||bytes.length>total-pending.bytes().size())throw new IllegalArgumentException("RESOURCE_PREVIEW_SEQUENCE");pending.bytes().writeBytes(bytes);if(pending.bytes().size()==total){PENDING.remove(packet.requestId());show(packet.requestId(),pending);}}catch(Exception error){PENDING.remove(packet.requestId());mc.gui.getChat().addClientSystemMessage(Component.literal("资源预览失败："+error.getMessage()));}}
 private static void show(UUID id,Pending p)throws Exception{NativeWorkspaceScreen.open();var host=NativeWorkspaceScreen.previewHost();var window=host.window("resource-"+id,p.header().get("name").getAsString(),520,380);window.body.clearAllChildren();if(p.bytes().size()==0){var scroll=WorkspacePanels.scroller(window.body);NativeEvidenceView.add(host,scroll,p.header().getAsJsonObject("content"));return;}
  if(TEXTURES.size()>=8)throw new IllegalStateException("RESOURCE_PREVIEW_OPEN_LIMIT");
  var raw=p.bytes().toByteArray();try(var input=javax.imageio.ImageIO.createImageInputStream(new ByteArrayInputStream(raw))){var readers=javax.imageio.ImageIO.getImageReaders(input);if(!readers.hasNext())throw new IllegalArgumentException("RESOURCE_IMAGE_FORMAT");var reader=readers.next();try{reader.setInput(input);if((long)reader.getWidth(0)*reader.getHeight(0)>dev.mineagent.runtime.api.model.ModelImage.MAX_PIXELS)throw new IllegalArgumentException("RESOURCE_IMAGE_PIXELS");}finally{reader.dispose();}}
  var image=com.mojang.blaze3d.platform.NativeImage.read(new ByteArrayInputStream(raw));int iw=image.getWidth(),ih=image.getHeight();var texture=net.minecraft.resources.Identifier.fromNamespaceAndPath("mineagent_runtime","resource_preview/"+id);Minecraft.getInstance().getTextureManager().register(texture,new net.minecraft.client.renderer.texture.DynamicTexture(()->"Resource preview",image));TEXTURES.put(texture,window);window.onClose(()->release(texture));
  var view=new UIElement();view.getLayout().widthPercent(100).flex(1).minHeight(0);var sprite=com.lowdragmc.lowdraglib2.gui.texture.SpriteTexture.of(texture);view.getStyle().backgroundTexture(com.lowdragmc.lowdraglib2.gui.texture.GuiTexture.of((context,x,y,w,h)->{float scale=Math.min(w/iw,h/ih);if(scale>0)context.drawTexture(sprite,x+(w-iw*scale)/2,y+(h-ih*scale)/2,iw*scale,ih*scale);}));window.body.addChild(view);window.body.addChild(WorkspacePanels.text(dev.mineagent.runtime.neoforge.client.language.ClientLanguage.t("已读取资源；预览不会执行文件。")));
 }
 private static void capture(UUID id,JsonObject request){var mc=Minecraft.getInstance();Object original=mc.getConnection();if(!ResourceCapturePreference.allowed()){reply(id,Map.of("error","CAPTURE_LOCAL_OPT_IN_REQUIRED"));return;}if(mc.player==null||mc.level==null||mc.screen instanceof dev.mineagent.runtime.neoforge.client.screen.NativeSecretScreen){reply(id,Map.of("error","CAPTURE_PRIVATE_SCREEN"));return;}
  String preview=request.has("previewId")?request.get("previewId").getAsString():"";Object originalLevel=mc.level,originalScreen=mc.screen;
  java.util.concurrent.CompletableFuture<NativePreview.CaptureRegion> region;
  try{region=preview.isBlank()?java.util.concurrent.CompletableFuture.completedFuture(null):NativePreview.prepareCapture(UUID.fromString(preview));}catch(Exception e){reply(id,Map.of("error",e.getMessage()));return;}
  region.whenComplete((area,error)->mc.execute(()->{if(original!=mc.getConnection()||originalLevel!=mc.level||originalScreen!=mc.screen||!ResourceCapturePreference.allowed()){reply(id,Map.of("error","CAPTURE_CONTEXT_CHANGED"));return;}if(error!=null){reply(id,Map.of("error","CAPTURE_PREVIEW_NOT_READY"));return;}
   net.minecraft.client.Screenshot.takeScreenshot(mc.getMainRenderTarget(),image->{
    final int width=image.getWidth(),height=image.getHeight();final int[] pixels;try(image){pixels=image.getPixels().clone();}
    IMAGES.execute(()->{try{var full=new java.awt.image.BufferedImage(width,height,java.awt.image.BufferedImage.TYPE_INT_ARGB);full.setRGB(0,0,width,height,pixels,0,width);java.awt.image.BufferedImage selected=full;if(area!=null){int x=(int)Math.floor(area.x()*width),y=(int)Math.floor(area.y()*height),w=(int)Math.ceil(area.width()*width),h=(int)Math.ceil(area.height()*height);if(x<0||y<0||w<1||h<1||x+w>width||y+h>height)throw new IllegalArgumentException("CAPTURE_PREVIEW_OUTSIDE");selected=full.getSubimage(x,y,w,h);}var png=dev.mineagent.runtime.worker.resources.ResourceImages.encode(selected,dev.mineagent.runtime.api.model.ModelImage.MAX_PIXELS);selected.flush();full.flush();byte[] bytes=png.bytes();mc.execute(()->{if(original!=mc.getConnection()||originalLevel!=mc.level||originalScreen!=mc.screen||!ResourceCapturePreference.allowed()){reply(id,Map.of("error","CAPTURE_CONTEXT_CHANGED"));return;}if(area!=null&&!NativePreview.captureCurrent(area)){reply(id,Map.of("error","CAPTURE_PREVIEW_CHANGED"));return;}for(int at=0;at<bytes.length;at+=18000)reply(id,Map.of("offset",at,"total",bytes.length,"data",Base64.getEncoder().encodeToString(Arrays.copyOfRange(bytes,at,Math.min(bytes.length,at+18000)))));});}catch(Exception e){mc.execute(()->reply(id,Map.of("error","CAPTURE_FAILED")));}});
   });
  }));
 }
 private static void reply(UUID id,Map<String,Object> data){if(Minecraft.getInstance().getConnection()!=null)net.neoforged.neoforge.client.network.ClientPacketDistributor.sendToServer(new UiPayloads.Command(id,"resourceViewReply",new Gson().toJson(data)));}
 private NativeResourceView(){}
}
